// --------- Auth helpers ---------
function getStoredUser() {
  const raw = localStorage.getItem('local_user');
  return raw ? JSON.parse(raw) : null;
}

function storeUser(user) {
  localStorage.setItem('local_user', JSON.stringify(user));
}

export const supabase = {
  from: (table) => builder(table),
  auth: {
    signInWithPassword: async ({ email, password }) => {
      const staff = getTable('staff');
      const user = staff.find(u => u.email === email && u.pin_code === password);
      if (!user) return { error: { message: 'Invalid credentials' } };
      storeUser(user);
      return { data: { user }, error: null };
    },
    signOut: async () => {
      localStorage.removeItem('local_user');
      return { error: null };
    },
    getSession: async () => {
      const user = getStoredUser();
      if (!user) return { data: { session: null } };
      return {
        data: {
          session: {
            user,
            access_token: 'offline-token',
            refresh_token: 'offline-refresh'
          }
        }
      };
    },
    onAuthStateChange: (cb) => {
      const user = getStoredUser();
      const session = user ? { user, access_token: 'offline-token' } : null;
      setTimeout(() => cb('SIGNED_IN', { user: session?.user }), 10);
      return { data: { subscription: { unsubscribe: () => {} } } };
    },
    setSession: async () => {
      // Always succeed in offline mode
      return { error: null };
    },
    signUp: async ({ email, password, options }) => {
      // Create new staff user without affecting current session
      const staff = getTable('staff');
      const newUser = {
        id: generateID(),
        email,
        pin_code: password,
        full_name: options?.data?.full_name || 'New User',
        role: 'cashier',
        is_active: true,
        store_id: null
      };
      saveTable('staff', [...staff, newUser]);
      return { data: { user: newUser }, error: null };
    }
  },
  storage: {
    from: () => ({
      upload: async () => ({ error: null }),
      getPublicUrl: () => ({ data: { publicUrl: '' } })
    })
  },
  rpc: () => ({ error: null })
};
